import json,re,csv
from collections import defaultdict

q=json.load(open('query.json'))
user,target=q['user'],q['target']

grants=defaultdict(set)
res=defaultdict(set)
for line in open('bindings.yaml'):
    m=re.search(r'\{(.*)\}',line)
    if not m: continue
    d={}
    for part in m.group(1).split(','):
        k,_,v=part.partition(':')
        d[k.strip()]=v.strip()
    if 'principal' in d: grants[d['principal']].add(d['role'])
    elif 'resource' in d: res[d['role']].add(d['resource'])

parents=defaultdict(set)
with open('membership.csv') as f:
    r=csv.reader(f); next(r)
    for row in r:
        if len(row)==2: parents[row[0].strip()].add(row[1].strip())

inh=defaultdict(set)
pats=[(r'Every permission of role (\S+) is also a permission of role (\S+?)\.',1),
      (r'Holders of role (\S+) receive the permissions of role (\S+?)\.',0),
      (r'Role (\S+) inherits all permissions of role (\S+?)\.',0)]
for line in open('inheritance.txt'):
    line=line.strip()
    for p,rev in pats:
        m=re.fullmatch(p,line)
        if m:
            a,b=m.group(1),m.group(2)
            if rev: inh[b].add(a)
            else: inh[a].add(b)
            break

principals={user}; stack=[user]
while stack:
    x=stack.pop()
    for g in parents[x]:
        if g not in principals:
            principals.add(g); stack.append(g)

roles=set()
for p in principals: roles|=grants[p]
# expand inherited roles
eff=set(roles)
for r0 in roles: eff|=inh[r0]

reach=any(target in res[r0] for r0 in eff)
print(json.dumps({'reachable':reach},separators=(',',':')))

