import json, re, csv

def load_bindings(path):
    grants = {}
    res = {}
    with open(path) as f:
        for line in f:
            m = re.search(r'\{(.*)\}', line)
            if not m:
                continue
            d = {}
            for part in m.group(1).split(','):
                if ':' in part:
                    k, v = part.split(':', 1)
                    d[k.strip()] = v.strip()
            if 'principal' in d and 'role' in d:
                grants.setdefault(d['principal'], set()).add(d['role'])
            elif 'role' in d and 'resource' in d:
                res.setdefault(d['role'], set()).add(d['resource'])
    return grants, res

def load_membership(path):
    parent = {}
    with open(path, newline='') as f:
        r = csv.DictReader(f)
        for row in r:
            parent[row['member'].strip()] = row['group'].strip()
    return parent

def load_inheritance(path):
    inh = {}
    pats = [
        (re.compile(r'Every permission of role (\S+) is also a permission of role (\S+?)\.?$'), lambda a, b: (b, a)),
        (re.compile(r'Holders of role (\S+) receive the permissions of role (\S+?)\.?$'), lambda a, b: (a, b)),
        (re.compile(r'Role (\S+) inherits all permissions of role (\S+?)\.?$'), lambda a, b: (a, b)),
    ]
    with open(path) as f:
        for line in f:
            line = line.strip()
            for p, fn in pats:
                m = p.match(line)
                if m:
                    src, dst = fn(m.group(1), m.group(2))
                    inh.setdefault(src, set()).add(dst)
                    break
    return inh

def main():
    q = json.load(open('query.json'))
    user, target = q['user'], q['target']
    grants, res = load_bindings('bindings.yaml')
    parent = load_membership('membership.csv')
    inh = load_inheritance('inheritance.txt')
    principals = {user}
    cur = user
    while cur in parent and parent[cur] not in principals:
        cur = parent[cur]
        principals.add(cur)
    roles = set()
    stack = [r for p in principals for r in grants.get(p, ())]
    while stack:
        r = stack.pop()
        if r in roles:
            continue
        roles.add(r)
        stack.extend(inh.get(r, ()))
    ok = any(target in res.get(r, ()) for r in roles)
    print(json.dumps({'reachable': ok}, separators=(',', ':')))

main()

This is the complete, case-sensitive, monotone RBAC policy. There are no denies,
wildcards, implicit grants, or external memberships. Identifiers are exact strings.
CSV member,group means member belongs to group, transitively through nested groups.
YAML principal,role grants that role to the principal (user or group); role,resource
lets holders of that role access the resource. Repeated principals accumulate grants.
Prose inheritance means the named inheriting role receives all permissions of the
other role, transitively. Access is a directed path through these facts.

